def load_csv_rows(path: Path):
    with path.open(newline='') as f:
        return list(csv.DictReader(f))


def as_int(value, *, field_name: str):
    if value is None:
        raise ValueError(f"Missing int field {field_name}")
    s = str(value).strip()
    if s == '':
        raise ValueError(f"Blank int field {field_name}")
    return int(s)


def as_float(value, *, field_name: str):
    if value is None:
        raise ValueError(f"Missing float field {field_name}")
    s = str(value).strip()
    if s == '':
        raise ValueError(f"Blank float field {field_name}")
    return float(s)


def money(x: float) -> float:
    # Keep as float (not Decimal) per task requirements; mitigate common binary rounding artifacts.
    return float(round(x + 1e-12, 2))


def flatten_panels(panel_manifest_obj):
    # Task text says panel_manifest.json is a list of panel objects.
    # The actual file may wrap panels in service clusters; support both without mutating semantics.
    if isinstance(panel_manifest_obj, list):
        return panel_manifest_obj

    if isinstance(panel_manifest_obj, dict) and 'service_clusters' in panel_manifest_obj:
        panels = []
        for cluster in panel_manifest_obj.get('service_clusters', []):
            for p in cluster.get('panels', []):
                panels.append(p)
        return panels

    raise ValueError('Unrecognized panel_manifest.json structure; expected list or {service_clusters: [...]}')


