#!/usr/bin/env python3
import csv
import json
from pathlib import Path

ROOT = Path('/root')


def load_json(path: Path):
    with path.open() as f:
        return json.load(f)


def load_csv_rows(path: Path):
    with path.open(newline='') as f:
        return list(csv.DictReader(f))


def as_int(value, *, field_name: str):
    if value is None:
        raise ValueError(f"Missing int field {field_name}")
    s = str(value).strip()
    if s == '':
        raise ValueError(f"Blank int field {field_name}")
    return int(s)


def as_float(value, *, field_name: str):
    if value is None:
        raise ValueError(f"Missing float field {field_name}")
    s = str(value).strip()
    if s == '':
        raise ValueError(f"Blank float field {field_name}")
    return float(s)


def money(x: float) -> float:
    # Keep as float (not Decimal) per task requirements; mitigate common binary rounding artifacts.
    return float(round(x + 1e-12, 2))


def flatten_panels(panel_manifest_obj):
    # Task text says panel_manifest.json is a list of panel objects.
    # The actual file may wrap panels in service clusters; support both without mutating semantics.
    if isinstance(panel_manifest_obj, list):
        return panel_manifest_obj

    if isinstance(panel_manifest_obj, dict) and 'service_clusters' in panel_manifest_obj:
        panels = []
        for cluster in panel_manifest_obj.get('service_clusters', []):
            for p in cluster.get('panels', []):
                panels.append(p)
        return panels

    raise ValueError('Unrecognized panel_manifest.json structure; expected list or {service_clusters: [...]}')


def normalize_holdouts(holdouts_obj):
    # Task text says holdouts.json is a list; actual file may be {"holdouts": [...]}
    if isinstance(holdouts_obj, list):
        return holdouts_obj
    if isinstance(holdouts_obj, dict) and 'holdouts' in holdouts_obj:
        return holdouts_obj.get('holdouts', [])
    raise ValueError('Unrecognized holdouts.json structure; expected list or {holdouts: [...]}')


def main():
    panel_manifest_obj = load_json(ROOT / 'panel_manifest.json')
    shipper_cost_rows = load_csv_rows(ROOT / 'shipper_cost.csv')
    contract_rows = load_csv_rows(ROOT / 'contract_terms.csv')
    network_rows = load_csv_rows(ROOT / 'network_adjustments.csv')
    override_rows = load_csv_rows(ROOT / 'lab_capacity_overrides.csv')
    holdouts_obj = load_json(ROOT / 'holdouts.json')
    report_template = load_json(ROOT / 'report_template.json')

    all_panels = flatten_panels(panel_manifest_obj)
    holdouts = normalize_holdouts(holdouts_obj)

    # 2b – Filter panels
    review_panels = [p for p in all_panels if p.get('analysis_mode') == 'review']

    excluded_codes = {
        h.get('panel_code')
        for h in holdouts
        if h.get('holdout_state') == 'exclude' and h.get('panel_code')
    }

    retained_panels = [p for p in review_panels if p.get('panel_code') not in excluded_codes]
    if not retained_panels:
        raise RuntimeError('No retained panels after filtering (analysis_mode==review and holdouts exclusion).')

    # 2d – Network adjustment dict
    network_adj_by_tier = {}
    for r in network_rows:
        tier = (r.get('network_tier') or '').strip()
        if not tier:
            continue
        network_adj_by_tier[tier] = as_float(r.get('network_adjustment_per_run_per_lab_usd'), field_name='network_adjustment_per_run_per_lab_usd')

    # 2f – Shipper cost dict
    shipper_cost_by_class = {}
    for r in shipper_cost_rows:
        shipper_class = (r.get('shipper_class') or '').strip()
        if not shipper_class:
            continue
        shipper_cost_by_class[shipper_class] = as_float(r.get('shipper_cost_usd'), field_name='shipper_cost_usd')

    # 2e – Active labs overrides (highest numeric approved rev, non-empty rev and active_labs)
    override_by_panel_code = {}
    for r in override_rows:
        approval = (r.get('approval') or '').strip()
        if approval != 'approved':
            continue

        rev_raw = (r.get('rev') or '').strip()
        active_labs_raw = (r.get('active_labs') or '').strip()
        if not rev_raw or not active_labs_raw:
            continue

        panel_code = (r.get('panel_code') or '').strip()
        if not panel_code:
            continue

        # numeric comparison: accept int/float-like values
        rev_num = float(rev_raw)
        active_labs = int(active_labs_raw)

        prev = override_by_panel_code.get(panel_code)
        if prev is None or rev_num > prev['rev_num']:
            override_by_panel_code[panel_code] = {
                'rev_num': rev_num,
                'active_labs': active_labs,
            }

    # Index contract terms by panel_ref for faster matching
    contract_rows_by_ref = {}
    for r in contract_rows:
        ref = (r.get('panel_ref') or '').strip()
        if not ref:
            continue
        contract_rows_by_ref.setdefault(ref, []).append(r)

    # 2c – Resolve contract terms and 2g – Calculations
    runs_14 = 26
    runs_28 = 13

    panel_outputs = []

    for p in retained_panels:
        panel_code = str(p.get('panel_code') or '')
        panel_name = str(p.get('panel_name') or '')
        if not panel_code or not panel_name:
            raise ValueError(f"Panel missing required identifiers: panel_code={panel_code!r}, panel_name={panel_name!r}")

        alias_labels = p.get('alias_labels') or []
        if not isinstance(alias_labels, list):
            alias_labels = []

        lookup_refs = {panel_name, *[str(a) for a in alias_labels if a is not None]}

        matching = []
        for ref in lookup_refs:
            for r in contract_rows_by_ref.get(ref, []):
                if (r.get('status_flag') or '').strip() == 'current':
                    matching.append(r)

        if not matching:
            raise ValueError(f"No current contract term found for panel_code={panel_code} using refs={sorted(lookup_refs)}")

        best_row = max(matching, key=lambda r: (r.get('effective_week') or ''))
        base = as_float(best_row.get('base_payment_per_run_per_lab_usd'), field_name='base_payment_per_run_per_lab_usd')

        network_tier = str(p.get('network_tier') or '')
        adj = float(network_adj_by_tier.get(network_tier, 0.0))

        shipper_class = str(p.get('shipper_class') or '')
        if shipper_class not in shipper_cost_by_class:
            raise ValueError(f"No shipper cost found for shipper_class={shipper_class!r} (panel_code={panel_code})")
        shipper = float(shipper_cost_by_class[shipper_class])

        if panel_code in override_by_panel_code:
            labs = int(override_by_panel_code[panel_code]['active_labs'])
            labs_source = 'override'
        else:
            labs = as_int(p.get('default_active_labs'), field_name='default_active_labs')
            labs_source = 'default_active_labs'

        tests_14 = as_int(p.get('tests_per_lab_per_run_14_day'), field_name='tests_per_lab_per_run_14_day')
        tests_28 = as_int(p.get('tests_per_lab_per_run_28_day'), field_name='tests_per_lab_per_run_28_day')
        reagent = as_float(p.get('reagent_cost_per_1000_tests_usd'), field_name='reagent_cost_per_1000_tests_usd')

        total_payment = base + adj

        annual_revenue_14 = total_payment * labs * runs_14
        annual_revenue_28 = total_payment * labs * runs_28

        annual_reagent_cost_14 = reagent * labs * tests_14 * runs_14 / 1000.0
        annual_reagent_cost_28 = reagent * labs * tests_28 * runs_28 / 1000.0

        annual_shipper_cost_14 = shipper * runs_14
        annual_shipper_cost_28 = shipper * runs_28

        annual_margin_14 = annual_revenue_14 - annual_reagent_cost_14 - annual_shipper_cost_14
        annual_margin_28 = annual_revenue_28 - annual_reagent_cost_28 - annual_shipper_cost_28
        difference = annual_margin_28 - annual_margin_14

        panel_outputs.append({
            'panel_code': panel_code,
            'panel_name': panel_name,
            'network_tier': network_tier,
            'shipper_class': shipper_class,
            'contract_panel_ref_used': str(best_row.get('panel_ref') or ''),
            'contract_effective_week_used': str(best_row.get('effective_week') or ''),
            'active_labs': int(labs),
            'active_labs_source': labs_source,
            'tests_per_lab_per_run_14_day': int(tests_14),
            'tests_per_lab_per_run_28_day': int(tests_28),
            'reagent_cost_per_1000_tests_usd': money(reagent),
            'base_payment_per_run_per_lab_usd': money(base),
            'network_adjustment_per_run_per_lab_usd': money(adj),
            'total_payment_per_run_per_lab_usd': money(total_payment),
            'shipper_cost_per_run_usd': money(shipper),
            'annual_revenue_14_day_usd': money(annual_revenue_14),
            'annual_revenue_28_day_usd': money(annual_revenue_28),
            'annual_reagent_cost_14_day_usd': money(annual_reagent_cost_14),
            'annual_reagent_cost_28_day_usd': money(annual_reagent_cost_28),
            'annual_shipper_cost_14_day_usd': money(annual_shipper_cost_14),
            'annual_shipper_cost_28_day_usd': money(annual_shipper_cost_28),
            'annual_margin_14_day_usd': money(annual_margin_14),
            'annual_margin_28_day_usd': money(annual_margin_28),
            'annual_margin_difference_28_minus_14_usd': money(difference),
        })

    panel_outputs.sort(key=lambda x: x['panel_code'])

    total_14 = money(sum(p['annual_margin_14_day_usd'] for p in panel_outputs))
    total_28 = money(sum(p['annual_margin_28_day_usd'] for p in panel_outputs))
    total_diff = money(total_28 - total_14)
    abs_diff = money(abs(total_28 - total_14))

    threshold = 6000.0
    decision = 'adopt_28_day' if abs_diff < threshold else 'keep_14_day'
    justification = f"Absolute annual margin difference is ${abs_diff:,.2f} vs $6,000 threshold."

    out = {
        # Preserve metadata and audit_notes exactly.
        'metadata': report_template.get('metadata'),
        'audit_notes': report_template.get('audit_notes'),
        'analysis': {
            'assumptions': {
                'runs_per_year_14_day': 26,
                'runs_per_year_28_day': 13,
                'switch_threshold_usd': 6000,
                'override_rule': 'highest numeric approved rev with non-empty active_labs, else default_active_labs',
                'holdout_rule': 'exclude holdout_state=exclude',
                'adjustment_rule': 'missing network_tier adjustment defaults to 0.0',
            },
            'panels': panel_outputs,
            'totals': {
                'total_annual_margin_14_day_usd': float(total_14),
                'total_annual_margin_28_day_usd': float(total_28),
                'total_annual_margin_difference_28_minus_14_usd': float(total_diff),
                'total_annual_margin_abs_difference_usd': float(abs_diff),
            },
            'recommendation': {
                'decision': decision,
                'justification': justification,
            },
        },
    }

    with (ROOT / 'diagpanel_policy_report.json').open('w') as f:
        json.dump(out, f, indent=2)

    with (ROOT / 'diagpanel_policy_summary.md').open('w') as f:
        lines = [
            f"Total 14-day annual margin: ${float(total_14):,.2f}",
            f"Total 28-day annual margin: ${float(total_28):,.2f}",
            f"Absolute difference: ${float(abs_diff):,.2f}",
            f"Decision: {decision}",
        ]
        f.write("\n".join(lines) + "\n")


if __name__ == '__main__':
    main()

